css:
.btn {
  width: 170px;
  height: 60px;
  font-size: 18px;
  background: #fff;
  border: none;
  border-radius: 50px;
  color: #000;
  outline: none;
  cursor: pointer;
  transition: all 0.4s;
}

.btn:hover {
  box-shadow: inset 0 0 0 4px #a53860, inset 0 0 0 8px #da627d,
    inset 0 0 0 12px #ffa5ab;
  background: #450920;
  font-size: 20px;
  color: #fff;
}

.btn:active {
  width: 160px;
  height: 50px;
  box-shadow: inset 0 0 0 3px #a53860, inset 0 0 0 6px #da627d,
    inset 0 0 0 9px #ffa5ab;
  font-size: 19px;
}
